n = 40
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def greedy_independent_set(adj_orig):
    adj = [set(a) for a in adj_orig]
    available = set(range(n))
    selected = []
    while available:
        v = min(available, key=lambda x: len(adj[x]))
        selected.append(v)
        to_remove = {v} | adj[v]
        for u in to_remove:
            if u in available:
                available.remove(u)
                for w in adj[u]:
                    if w in available:
                        adj[w].discard(u)
    return selected

ind_set = greedy_independent_set(adj)
print("Greedy independent set size:", len(ind_set))
print("Set:", sorted(ind_set))

# Verify
ind_set_set = set(ind_set)
for u,v in edges:
    if u in ind_set_set and v in ind_set_set:
        print(f"ERROR: edge ({u},{v}) both in set")
print("Verification done")
